import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Collision (PX4)","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/px4/collision.md","filePath":"en/qgc-user-guide/setup_view/px4/collision.md"}`),a={name:`en/qgc-user-guide/setup_view/px4/collision.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="collision-px4" tabindex="-1">Collision (PX4) <a class="header-anchor" href="#collision-px4" aria-label="Permalink to “Collision (PX4)”">​</a></h1><p>The Collision page configures collision prevention, which keeps a multicopter away from obstacles seen by distance sensors or a companion computer. Collision prevention only works in Position mode. It is designed for PX4 1.17 or later.</p><p>The page only appears when the connected vehicle has the collision prevention settings. The choices, units and limits of each setting come from the vehicle&#39;s parameter metadata. Changes are written to the vehicle immediately and can be made in flight.</p><h2 id="collision-prevention" tabindex="-1">Collision Prevention <a class="header-anchor" href="#collision-prevention" aria-label="Permalink to “Collision Prevention”">​</a></h2><ul><li><strong>Prevention</strong> — the minimum distance the vehicle keeps to obstacles (<em>0</em> or negative turns collision prevention off), and whether it may move in directions where no sensor is looking.</li><li><strong>Tuning</strong> — the combined sensor and control delay, and how far the vehicle may steer left or right of the commanded direction. The defaults suit most vehicles.</li></ul><h2 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to “Display”">​</a></h2><p><strong>Show obstacle distance overlay</strong> draws the distances measured around the vehicle on the fly view.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};